    avoid_spine = _spine_raw(); avoid_spine["segments"][0] = dict(avoid_spine["segments"][0], visual_motif="提前揭示第三方"); negatives["spine_must_avoid"] = any(e["code"] == "SPINE_MUST_AVOID_VIOLATION" for e in validate_spine(normalize_spine(avoid_spine, scene_id=scene["scene_id"], strategy_fingerprint=strategy["strategy_fingerprint"])["ir"], scene=scene, strategy=strategy)["hard_errors"])
    bad_skeleton = _skeleton_raw(); bad_skeleton["nodes"][0] = dict(bad_skeleton["nodes"][0], camera_movement="PAN"); negatives["skeleton_camera_forbidden"] = normalize_skeleton(bad_skeleton, scene_id=scene["scene_id"], spine_fingerprint=spine["spine_fingerprint"])["status"] == "FAIL"
    phase_skeleton = _skeleton_raw(); phase_skeleton["nodes"][0] = dict(phase_skeleton["nodes"][0], phase_id="P02"); negatives["skeleton_phase_membership"] = validate_skeleton(normalize_skeleton(phase_skeleton, scene_id=scene["scene_id"], spine_fingerprint=spine["spine_fingerprint"])["ir"], spine=spine["ir"], scene=scene, strategy=strategy)["status"] == "FAIL"
    identity_skeleton = _skeleton_raw(); identity_skeleton["nodes"][0] = dict(identity_skeleton["nodes"][0], subjects=["character:999"]); negatives["skeleton_identity_binding"] = validate_skeleton(normalize_skeleton(identity_skeleton, scene_id=scene["scene_id"], spine_fingerprint=spine["spine_fingerprint"])["ir"], spine=spine["ir"], scene=scene, strategy=strategy)["status"] == "FAIL"
    missing_reaction = _skeleton_raw(); missing_reaction["nodes"][1] = dict(missing_reaction["nodes"][1], stimulus_beat_refs=[], stimulus_event_key=None); negatives["reaction_stimulus_required"] = validate_skeleton(normalize_skeleton(missing_reaction, scene_id=scene["scene_id"], spine_fingerprint=spine["spine_fingerprint"])["ir"], spine=spine["ir"], scene=scene, strategy=strategy)["status"] == "FAIL"
    ambiguous = _skeleton_raw(); ambiguous["nodes"] = [dict(ambiguous["nodes"][0], beat_refs=["beat:2"]), dict(ambiguous["nodes"][0], segment_key="SEG01", beat_refs=["beat:2"]), dict(ambiguous["nodes"][1], segment_key="SEG02", stimulus_beat_refs=["beat:2"])]
    amb = bind_topology(normalize_skeleton(ambiguous, scene_id=scene["scene_id"], spine_fingerprint=spine["spine_fingerprint"])["ir"], semantic_events=events); negatives["ambiguous_binding"] = any(e["code"] == "GRAPH_BINDING_AMBIGUOUS" for e in amb["errors"])
    missing = _skeleton_raw(); missing["nodes"] = [dict(missing["nodes"][1], stimulus_beat_refs=["beat:99"])]
    mis = bind_topology(normalize_skeleton(missing, scene_id=scene["scene_id"], spine_fingerprint=spine["spine_fingerprint"])["ir"], semantic_events=events); negatives["missing_binding"] = any(e["code"] == "GRAPH_BINDING_TARGET_MISSING" for e in mis["errors"])
    future = _skeleton_raw(); future["nodes"] = [dict(future["nodes"][1], segment_key="SEG01", phase_id="P01", beat_refs=["beat:1"], stimulus_beat_refs=["beat:2"]), dict(future["nodes"][0], segment_key="SEG02", phase_id="P02", beat_refs=["beat:2"])]
    fut = bind_topology(normalize_skeleton(future, scene_id=scene["scene_id"], spine_fingerprint=spine["spine_fingerprint"])["ir"], semantic_events=events); negatives["future_binding"] = any(e["code"] == "GRAPH_BINDING_ORDER_INVALID" for e in fut["errors"])
    negatives["self_edge"] = any(e["code"] == "GRAPH_SELF_EDGE_INVALID" for e in validate_bound_edges([{"edge_type": "REACTION_TO", "from_node_id": "ST01", "to_node_id": "ST01"}]))
    mutation = {"expansions": [dict(expansion["expansions"][0], phase_id="P99"), expansion["expansions"][1]]}; negatives["expansion_topology_mutation"] = validate_atomic_expansion(bound, mutation)["status"] == "FAIL"
    unknown = {"expansions": list(expansion["expansions"]) + [dict(expansion["expansions"][0], node_id="ST99")]}; negatives["expansion_unknown_node"] = validate_atomic_expansion(bound, unknown)["status"] == "FAIL"
    duplicate = {"expansions": [expansion["expansions"][0], expansion["expansions"][0]]}; negatives["expansion_duplicate_node"] = validate_atomic_expansion(bound, duplicate)["status"] == "FAIL"
    positive = {"spine": spine_q, "skeleton": skeleton_q, "binder": bound["binding_status"], "expansion": expansion_q, "candidate_deterministic": candidate1.get("architecture_candidate_fingerprint") == candidate2.get("architecture_candidate_fingerprint"), "candidate_ids": [s["shot_id"] for s in candidate1["candidate"]["shots"]] == ["SA01", "SA02"], "reaction_ref_program_owned": candidate1["candidate"]["shots"][1].get("stimulus_ref") == "shot:SA01", "reordered_expansion_stable": candidate1.get("architecture_candidate_fingerprint") == candidate2.get("architecture_candidate_fingerprint")}
    _write(ART / "director-quality-v3-shot-architecture-redesign-positive-fixtures.json", positive); _write(ART / "director-quality-v3-shot-architecture-redesign-negative-fixtures.json", negatives); _write(ART / "director-quality-v3-shot-architecture-redesign-binding-tests.json", {"unique": bound["binding_status"] == "PASS", "ambiguous": negatives["ambiguous_binding"], "missing": negatives["missing_binding"], "future": negatives["future_binding"], "self_edge": negatives["self_edge"]})
