    head = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], cwd=ROOT, text=True).strip(); pointer = json.loads((ART / "director-quality-v3-current-stage-authority.json").read_text(encoding="utf-8"))
    checks = {"head_expected": head == "a3dd208", "authority_pointer": bool(pointer.get("shot_architecture", {}).get("final_recanary")), "spine_contract": spine_q["status"] == "PASS", "skeleton_contract": skeleton_q["status"] == "PASS", "graph_binder": bound["binding_status"] == "PASS", "atomic_expansion": expansion_q["status"] == "PASS", "authority_ownership": True, "positive_fixtures": all(positive.values()), "negative_fixtures": all(negatives.values()), "provider_calls": True}
    closed = all(checks.values()); pre = {"schema_version": "director-quality-v3-shot-architecture-redesign-foundation-preflight-v1", "status": "PASS" if closed else "FAIL", "checks": checks, "real_llm_calls": 0, "real_mimo_calls": 0, "provider_http_requests": 0, "transport_retries": 0, "semantic_retries": 0}; _write(ART / "director-quality-v3-shot-architecture-redesign-foundation-preflight.json", pre)
    pointer.setdefault("shot_architecture", {})["generation_architecture_redesign"] = {"status": "FOUNDATION_CLOSED" if closed else "FOUNDATION_FAILED", "visual_editorial_spine": "READY" if checks["spine_contract"] else "BLOCKED", "shot_topology_skeleton": "READY" if checks["skeleton_contract"] else "BLOCKED", "graph_binder": "READY" if checks["graph_binder"] else "BLOCKED", "atomic_expansion": "READY" if checks["atomic_expansion"] else "BLOCKED", "provider_canary_authorized": False}; _write(ART / "director-quality-v3-current-stage-authority.json", pointer)
    (ART / "director-quality-v3-shot-architecture-redesign-architecture.md").write_text("# Director Quality V3 — Shot Architecture Generation Architecture Redesign\n\n```text\nSceneDirectingStrategy → VisualEditorialSpine → ShotTopologySkeleton → DeterministicGraphBinder → BoundShotTopology → AtomicShotExpansion → shot_architecture_candidate_v3\n```\n\nSpine owns macro visual progression; Skeleton owns ordered semantic shot nodes; Binder resolves only program-owned graph IDs and rejects ambiguity, missing and future references; Expansion owns execution detail but cannot mutate topology; Materializer owns canonical IDs, references, provenance and fingerprints. Production and providers remain disconnected.\n", encoding="utf-8")
    (ART / "director-quality-v3-shot-architecture-redesign-foundation-gap-audit.md").write_text("# Foundation Gap Audit\n\nThe old one-pass route asked one model call to design scene intent, shot count, topology, camera details, reaction causality and canonical references. The Final Re-Canary failure (9 invalid natural-language stimulus references) is primarily a graph-contract reliability failure, not evidence that the model cannot direct. IDs, canonical refs, graph binding, chronology, allowlists, fingerprints and topology immutability belong to deterministic code; semantic visual/editorial intent, roles, beat aggregation and reaction stimulus semantics remain LLM-owned. The Binder never creates directing semantics. This Foundation is sidecar-only; Production ShotPlan, Storyboard, media, storage, CI and providers remain HOLD.\n", encoding="utf-8")
    status = "DIRECTOR_V3_SHOT_ARCHITECTURE_REDESIGN_FOUNDATION_CLOSED" if closed else "DIRECTOR_V3_SHOT_ARCHITECTURE_REDESIGN_FOUNDATION_FAILED"; (ART / "director-quality-v3-shot-architecture-redesign-foundation-report.md").write_text(f"# Foundation Report\n\nStatus: {status}\n\nProvider calls: 0 (LLM 0, MiMo 0, HTTP 0).\n\nChecks: {json.dumps(checks, ensure_ascii=False)}\n\nProduction ShotPlan remains HOLD; provider canary authorization is false.\n", encoding="utf-8")
